insert into public.tarihiz_topics(id,title,question,sources,demo) values
('00000000-0000-4000-8000-000000000001', 'Kasabada pazar hayatı', 'Bu günlük, yolun pazar hayatına etkisi hakkında hangi yorumu destekliyor?', '[{"id": "k1", "title": "Bir yolcunun günlüğü", "creator": "Kurmaca anlatıcı A", "date": "Belirtilmemiş", "place": "Kurmaca kasaba", "purpose": "Kişisel yolculuk deneyimini kaydetmek", "type": "Günlük — örnek öğretim metni", "reference": "Arayüz testi için oluşturulmuştur; gerçek tarihsel belge değildir.", "image": null, "verified": false, "text": "Yeni yol açıldıktan sonra kasabaya daha kısa sürede ulaştım. Pazarda önceki ziyaretimden daha çok tezgâh gördüm. Yolun kasabadaki ticareti canlandırdığını düşünüyorum.", "description": ""}]'::jsonb, true),
('00000000-0000-4000-8000-000000000002', 'Esnafın gündelik yaşamı', 'Bu mektuptan kasabadaki esnafın deneyimleri hakkında hangi sonuca ulaşabilirsin?', '[{"id": "k2", "title": "Bir esnafın mektubu", "creator": "Kurmaca anlatıcı B", "date": "Belirtilmemiş", "place": "Kurmaca kasaba", "purpose": "Dükkândaki gelişmeleri bir yakınına anlatmak", "type": "Mektup — örnek öğretim metni", "reference": "Arayüz testi için oluşturulmuştur; gerçek tarihsel belge değildir.", "image": null, "verified": false, "text": "Yol açıldığından beri dükkânımıza daha çok yolcu uğruyor. Ancak kış boyunca taşımacılık sık sık durdu. Komşu dükkânların bazılarında satışlar artarken bazılarında değişmedi.", "description": ""}]'::jsonb, true)
